verus! {

    /// Given n items in a row (indexed 1..=n) and an inspector coverage radius d,
    /// each inspector covers a contiguous block of length 2*d+1.
    /// This function returns the minimum number of inspectors needed to cover all n items,
    /// which is ceil(n / (2*d+1)).
    pub fn min_inspectors(n: i8, d: i8) -> (result: i8)
        requires 1 <= n && n <= 20
        requires 1 <= d && d <= 20
        ensures 1 <= result && result <= n
        ensures result == (n + (2*d + 1) - 1) / (2*d + 1)
    {
        // capacity of one inspector
        let cap = 2*d + 1;

        // rem = how many items still need covering
        let mut rem: i8 = n;
        // count = how many inspectors have been placed so far
        let mut count: i8 = 0;

        // Repeatedly place one inspector (covering `cap` items)
        while rem > 0 {
            invariant 0 <= rem && rem <= n;
            invariant 0 <= count && count <= n;
            // each placed inspector covers `cap` items, so:
            // count*cap + rem == original n
            invariant count * cap + rem == n;
            decreases rem;

            rem = rem - cap;
            count = count + 1;
        }

        // At loop exit rem <= 0, but also rem > -cap (since we subtracted cap
        // only when rem > 0), so -cap < rem <= 0.
        assert(rem <= 0);
        assert(rem > -cap);

        // From the invariant count*cap + rem == n, we get
        // n - rem == count*cap, and since -cap < rem <= 0,
        //   n <= count*cap < n + cap.
        assert(count * cap >= n);
        assert(count * cap < n + cap);

        // Hence count = ceil(n/cap) = (n + cap - 1) / cap
        assert(count == (n + cap - 1) / cap);

        // Finally record and return the answer
        result = count;
    }

}